import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();

        int[] parent = new int[P + 1];
        int[] rank = new int[P + 1];
        for (int i = 1; i <= P; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        Function<Integer, Integer> findp = new Function<Integer, Integer>() {
            public Integer apply(Integer x) {
                if (parent[x] != x) {
                    parent[x] = apply(parent[x]);
                }
                return parent[x];
            }
        };

        BiConsumer<Integer, Integer> union_sets = new BiConsumer<Integer, Integer>() {
            public void accept(Integer a, Integer b) {
                if (rank[a] >= rank[b]) {
                    parent[b] = a;
                    rank[a]++;
                } else {
                    parent[a] = b;
                    rank[b]++;
                }
            }
        };

        for (int i = 1; i <= P; i++) {
            int val = (int)((long)K * i % P);
            int pa = findp.apply(i);
            int pb = findp.apply(val);
            if (pa != pb) {
                union_sets.accept(pa, pb);
            }
        }

        Set<Integer> groupSet = new HashSet<>();
        for (int i = 1; i <= P; i++) {
            groupSet.add(findp.apply(i));
        }

        long ways;
        final long MOD = 1000000007L;

        BiFunction<Long, Long, Long> fast_pow = new BiFunction<Long, Long, Long>() {
            public Long apply(Long base, Long exp) {
                long res = 1;
                long b = base;
                long e = exp;
                while (e > 0) {
                    if ((e & 1) == 1) {
                        res = (res * b) % MOD;
                    }
                    b = (b * b) % MOD;
                    e >>= 1;
                }
                return res;
            }
        };

        if (K == 0) {
            ways = fast_pow.apply((long) P, (long) P - 1);
        } else if (K == 1) {
            ways = fast_pow.apply((long) P, (long) P);
        } else {
            ways = fast_pow.apply((long) P, (long) groupSet.size());
        }

        System.out.println(ways);
        sc.close();
    }
}
